using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey));

builder.Services.AddSingleton<NoteService>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about topics, " +
    "and the take_note tool to record important findings. After researching, provide a comprehensive summary.",
    [researchTools]);

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly. Search the web for relevant information, " +
        $"take notes on key findings, then provide a final summary.\n\nTopic: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Notes collected:");
var noteService = host.Services.GetRequiredService<NoteService>();
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"  • {note}");
}

