using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for web search and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(30),
    };

    private readonly NoteService _noteService;

    public ResearchTools(NoteService noteService)
    {
        _noteService = noteService;
    }

    [Description("Search the web for information on a given query. Returns a list of relevant results with titles and snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up on the web")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            var abstractText = response.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = response.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            if (response.TryGetProperty("RelatedTopics", out var relatedTopics)
                && relatedTopics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in relatedTopics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text)
                        && !string.IsNullOrWhiteSpace(text.GetString()))
                    {
                        results.Add(text.GetString()!);
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing the search query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to record an important finding during research. Use this to save key facts and insights.")]
    public string TakeNote(
        [Description("The note content to save — a key finding or insight")] string note)
    {
        Console.WriteLine($"  📝 Note taken: \"{note[..Math.Min(note.Length, 60)]}...\"");
        _noteService.AddNote(note);
        return $"Note saved successfully. Total notes: {_noteService.GetNotes().Count}";
    }
}

