 using var host = builder.Build();

 var chatClient = host.Services.GetRequiredService<IChatClient>();
 var noteService = host.Services.GetRequiredService<NoteService>();
 var researchTools = new ResearchTools(noteService);

 // Create AI tools from the ResearchTools methods
 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(researchTools.WebSearch),
     AIFunctionFactory.Create(researchTools.TakeNote),
 };

 // Build the agent with tools
 var agent = new ChatClientAgent(
     chatClient,
     instructions: "You are a research assistant. Use the WebSearch tool to find information about topics, " +
         "and the TakeNote tool to record important findings. After researching, provide a comprehensive summary " +
         "of what you learned. Always take notes on key findings before summarizing.",
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 var topic = args.Length > 0
     ? string.Join(' ', args)
     : "the latest advances in quantum computing in 2026";

 Console.WriteLine($"🔍 Researching: {topic}\n");

 var messages = new List<ChatMessage>
 {
     new(ChatRole.User,
         $"Research the following topic thoroughly. Search the web for relevant information, " +
         $"take notes on key findings, then provide a final summary.\n\nTopic: {topic}")
 };

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 var response = await agent.RunAsync(messages, options: runOptions);

 Console.WriteLine(response.Text);

 Console.WriteLine("\n\n📝 Notes collected:");
 foreach (var note in noteService.GetNotes())
 {
     Console.WriteLine($"  • {note}");
 }

 if (noteService.GetNotes().Count == 0)
 {
     Console.WriteLine("  (No notes were taken)");
 }
